import { useNavigate } from "react-router-dom";
import Navbar from "../components/Navbar";
import { useState, useEffect } from "react";
import { API } from "../api/api";

export default function Home() {
  const nav = useNavigate();

  const [polls, setPolls] = useState([]);
  const [surveys, setSurveys] = useState([]);
  const [category, setCategory] = useState("all");

  useEffect(() => {
    fetchPolls();
    fetchSurveys();
  }, []);

  const fetchPolls = async () => {
    try {
      const res = await API.get("/polls");
      setPolls(res.data || []);
    } catch {
      setPolls([]);
    }
  };

  const fetchSurveys = async () => {
    try {
      const res = await API.get("/surveys");
      setSurveys(res.data || []);
    } catch {
      setSurveys([]);
    }
  };

  const filteredPolls = polls.filter(p => {
    if (category === "all") return true;
    return (p.type || "").toLowerCase() === category.toLowerCase();
  });

  const filteredSurveys = surveys.filter(s => {
    if (category === "all") return true;
    return (s.category || "").toLowerCase() === category.toLowerCase();
  });

  return (
    <>
      <Navbar />

      <style>{`
        .home-container{
          min-height:100vh;
          padding:40px;
          color:#e5e7eb;
          background: linear-gradient(180deg, #0f172a 0%, #020617 100%);
        }

        /* HERO */
        .hero{
          max-width:900px;
          margin:0 auto 50px;
          text-align:center;
        }

        .hero h1{
          font-size:44px;
          font-weight:700;
          color:#f8fafc;
          margin-bottom:12px;
        }

        .hero-sub{
          font-size:18px;
          color:#94a3b8;
          margin-bottom:25px;
          line-height:1.6;
        }

        .hero-actions{
          display:flex;
          justify-content:center;
          gap:12px;
          flex-wrap:wrap;
        }

        .hero-btn{
          padding:10px 20px;
          border-radius:8px;
          font-weight:500;
          cursor:pointer;
          border:1px solid transparent;
          transition:all 0.2s ease;
        }

        .hero-btn.primary{
          background:#2563eb;
          color:white;
        }

        .hero-btn.primary:hover{
          background:#1d4ed8;
        }

        .hero-btn.secondary{
          background:transparent;
          border:1px solid #334155;
          color:#cbd5f5;
        }

        .hero-btn.secondary:hover{
          background:#111827;
        }

        /* CATEGORY */
        .category-bar{
          display:flex;
          justify-content:center;
          gap:10px;
          margin-bottom:30px;
          flex-wrap:wrap;
        }

        .category-bar button{
          padding:6px 14px;
          border-radius:6px;
          background:#020617;
          border:1px solid #1e293b;
          color:#cbd5f5;
          cursor:pointer;
          font-size:13px;
        }

        .active-cat{
          background:#1d4ed8 !important;
          color:white !important;
          border-color:#1d4ed8 !important;
        }

        /* MAIN */
        .container{
          display:flex;
          justify-content:center;
          gap:30px;
          flex-wrap:wrap;
        }

        /* CARD */
        .card{
          width:380px;
          border-radius:12px;
          background:#020617;
          border:1px solid #1e293b;
          padding:20px;
        }

        .title{
          font-size:18px;
          font-weight:600;
          margin-bottom:12px;
          color:#f1f5f9;
        }

        .item{
          padding:10px;
          margin:6px 0;
          background:#020617;
          border:1px solid #1e293b;
          border-radius:8px;
          cursor:pointer;
          transition:all 0.15s ease;
          font-size:14px;
        }

        .item:hover{
          background:#020617;
          border-color:#2563eb;
        }

        .btn{
          width:100%;
          padding:10px;
          margin-bottom:10px;
          border-radius:8px;
          border:none;
          cursor:pointer;
          font-weight:500;
          font-size:14px;
        }

        .poll-btn{
          background:#16a34a;
          color:white;
        }

        .poll-btn:hover{
          background:#15803d;
        }

        .survey-btn{
          background:#2563eb;
          color:white;
        }

        .survey-btn:hover{
          background:#1d4ed8;
        }
      `}</style>

      <div className="home-container">

        {/* HERO */}
        <div className="hero">
          <h1>Gather Insights. Make Better Decisions.</h1>
          <p className="hero-sub">
            Participate in polls and surveys to share your perspective and discover what others think.
          </p>

          <div className="hero-actions">
            <button
              className="hero-btn primary"
              onClick={() => nav("/polls")}
            >
              Browse Polls
            </button>

            <button
              className="hero-btn secondary"
              onClick={() => nav("/surveys")}
            >
              Browse Surveys
            </button>
          </div>
        </div>

        {/* CATEGORY */}
        <div className="category-bar">
          {["all", "student", "teacher", "general"].map(cat => (
            <button
              key={cat}
              onClick={() => setCategory(cat)}
              className={category === cat ? "active-cat" : ""}
            >
              {cat.toUpperCase()}
            </button>
          ))}
        </div>

        <div className="container">

          {/* POLLS */}
          <div className="card">
            <div className="title">Polls</div>

            <button
              className="btn poll-btn"
              onClick={() => nav("/polls")}
            >
              View All Polls
            </button>

            {filteredPolls.slice(0, 5).map(p => (
              <div
                key={p._id}
                className="item"
                onClick={() => nav(`/poll/${p._id}`)}
              >
                {p.question}
              </div>
            ))}
          </div>

          {/* SURVEYS */}
          <div className="card">
            <div className="title">Surveys</div>

            <button
              className="btn survey-btn"
              onClick={() => nav("/surveys")}
            >
              View All Surveys
            </button>

            {filteredSurveys.slice(0, 5).map(s => (
              <div
                key={s._id}
                className="item"
                onClick={() => nav(`/survey/${s._id}`)}
              >
                {s.title}
              </div>
            ))}
          </div>

        </div>
      </div>
    </>
  );
}
